mapper.select:
SELECT ca.attachment_id, ca.document_name, ca.description, ( SELECT wm_concat( faa.file_name ) modelName FROM fnd_atm_attachment faa, fnd_atm_attachment_multi faam WHERE faam.record_id = faa.source_pk_value AND faam.table_pk_value = ca.attachment_id AND faam.table_name = 'jczl_common_attachment' ) file_name FROM jczl_common_attachment ca
ca.source_category = 'con_contract_tariff_info'
and ca.source_id = #{tariffId}

SELECT ca.attachment_id, ca.document_name, ca.description, ca.document_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CONT.DOCUMENT_TYPE' AND code_value = ca.document_type ) document_type_n, ( SELECT s.description FROM sys_user s WHERE s.user_id = ca.created_by ) AS created_by_n, ca.last_update_date, ( SELECT wm_concat( faa.file_name ) modelName FROM fnd_atm_attachment faa, fnd_atm_attachment_multi faam WHERE faam.record_id = faa.source_pk_value AND faam.table_pk_value = ca.attachment_id AND faam.table_name = 'jczl_common_attachment' ) file_name FROM jczl_common_attachment ca
1=1
and ca.source_id = #{sourceId}
and ca.source_category = #{sourceCategory}

SELECT ca.source_id as cash_detail_id, ca.attachment_id, ca.document_name, ca.description, ca.document_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CONT.DOCUMENT_TYPE' AND code_value = ca.document_type ) document_type_n, ( SELECT s.description FROM sys_user s WHERE s.user_id = ca.created_by ) AS created_by_n, ca.last_update_date, ( SELECT wm_concat( faa.file_name ) modelName FROM fnd_atm_attachment faa, fnd_atm_attachment_multi faam WHERE faam.record_id = faa.source_pk_value AND faam.table_pk_value = ca.attachment_id AND faam.table_name = 'jczl_common_attachment' ) file_name FROM jczl_common_attachment ca
1=1
and ca.source_id = #{sourceId}
and ca.source_category = #{sourceCategory}

SELECT ca.source_id as disclosure_id, ca.attachment_id, ca.document_name, ca.description, ca.document_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CONT.DOCUMENT_TYPE' AND code_value = ca.document_type ) document_type_n, ( SELECT s.description FROM sys_user s WHERE s.user_id = ca.created_by ) AS created_by_n, ca.last_update_date, ( SELECT wm_concat( faa.file_name ) modelName FROM fnd_atm_attachment faa, fnd_atm_attachment_multi faam WHERE faam.record_id = faa.source_pk_value AND faam.table_pk_value = ca.attachment_id AND faam.table_name = 'jczl_common_attachment' ) file_name FROM jczl_common_attachment ca
1=1
and ca.source_id = #{sourceId}
and ca.source_category = #{sourceCategory}

SELECT ca.source_id as check_id, ca.attachment_id, ca.document_name, ca.description, ca.document_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CONT.DOCUMENT_TYPE' AND code_value = ca.document_type ) document_type_n, ( SELECT max( fat.last_update_date ) FROM fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'jczl_common_attachment' AND faam.table_pk_value = ca.attachment_id ) last_update_date, ( SELECT max( su.description ) FROM sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'jczl_common_attachment' AND faam.table_pk_value = ca.attachment_id AND su.user_id = fat.last_updated_by ) created_by_n, ( SELECT wm_concat( faa.file_name ) modelName FROM fnd_atm_attachment faa, fnd_atm_attachment_multi faam WHERE faam.record_id = faa.source_pk_value AND faam.table_pk_value = ca.attachment_id AND faam.table_name = 'jczl_common_attachment' ) file_name FROM jczl_common_attachment ca
1=1
and ca.source_id = #{sourceId}
and ca.source_category = #{sourceCategory}
